const input = $json;
const text = `${input.issue_summary} ${input.issue_description}`.toLowerCase();

let category = 'General Inquiry';
if (/bill|payment|invoice|charge|refund/.test(text)) category = 'Billing';
else if (/login|password|otp|access|locked/.test(text)) category = 'Account Access';
else if (/bug|crash|error|exception|fail/.test(text)) category = 'Bug Report';
else if (/feature|enhancement|request/.test(text)) category = 'Feature Request';
else if (/slow|latency|performance|timeout|upload/.test(text)) category = 'Technical Issue';

let priority = 'Medium';
if (/urgent|critical|production down|data loss|security/.test(text)) priority = 'Critical';
else if (/cannot|blocked|unable|outage|down/.test(text)) priority = 'High';
else if (/minor|question|clarification/.test(text)) priority = 'Low';

const stamp = new Date();
const ticketId = `TICK-${stamp.getFullYear()}${String(stamp.getMonth() + 1).padStart(2, '0')}${String(stamp.getDate()).padStart(2, '0')}-${Math.floor(Math.random() * 9000 + 1000)}`;

return [{
  json: {
    ...input,
    ticket_id: ticketId,
    category,
    priority,
    status: 'Open',
    created_at: stamp.toISOString(),
    updated_at: stamp.toISOString(),
    message: 'Your ticket has been created successfully.'
  }
}];
